using System;
using System.IO;
using System.Text;
using System.Text.Json;

namespace IPv8.Tests
{
    /// <summary>
    /// Loader for the Phase 1b golden vectors (contract/vectors-phase1b.json, copied next to the
    /// test assembly). The store/find TARGET key is sha1(b"ipv8-port-phase1b-target")[:20], as
    /// generated by contract/gen_vectors_phase1b.py.
    /// </summary>
    public static class Vectors1b
    {
        private static readonly Lazy<JsonElement> Root = new Lazy<JsonElement>(LoadRoot);

        private static JsonElement LoadRoot()
        {
            var assemblyLocation = AppContext.BaseDirectory;
            var path = Path.Combine(assemblyLocation, "vectors-phase1b.json");
            var json = File.ReadAllText(path);
            return JsonDocument.Parse(json).RootElement.Clone();
        }

        private static JsonElement RootElement => Root.Value;

        public static string Meta(string key) => RootElement.GetProperty("meta").GetProperty(key).GetString();

        public static string MetaKey(string key) => RootElement.GetProperty("meta").GetProperty("keys").GetProperty(key).GetString();

        public static string Routing(string key) => RootElement.GetProperty("routing").GetProperty(key).GetString();

        public static string TokenStr => RootElement.GetProperty("token").GetProperty("str_node_a").GetString();

        public static string TokenHex => RootElement.GetProperty("token").GetProperty("token_a_hex").GetString();

        public static string TokenSecretHex => Meta("token_secret_hex");

        public static string SerializerExtras(string key)
            => RootElement.GetProperty("serializer_extras").GetProperty(key).GetString();

        public static string Packet(string name)
            => RootElement.GetProperty("packet_" + name + "_hex").GetString();

        /// <summary>The TARGET key used by the DHT golden packets and the loopback smoke test.</summary>
        public static byte[] Target()
            => Util.Slice(Util.Sha1(Encoding.UTF8.GetBytes("ipv8-port-phase1b-target")), 0, 20);
    }
}
